import java.util.*;

public class Solution {
    static class Agenda {
        private final Map<String, String> contatos = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);

        void adicionar(String nome, String telefone) {
            if (nome == null || nome.isBlank() || telefone == null || telefone.isBlank()) {
                throw new IllegalArgumentException("nome e telefone obrigatorios");
            }
            contatos.put(nome, telefone);
        }

        boolean remover(String nome) {
            return contatos.remove(nome) != null;
        }

        Optional<String> buscar(String nome) {
            return Optional.ofNullable(contatos.get(nome));
        }

        List<String> listarOrdenado() {
            return new ArrayList<>(contatos.keySet());
        }

        int tamanho() { return contatos.size(); }
    }
}

