import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void adicionaEBuscaCaseInsensitive() {
        var a = new Solution.Agenda();
        a.adicionar("Ana", "111");
        assertEquals("111", a.buscar("ana").orElseThrow());
    }

    @Test void substituiTelefone() {
        var a = new Solution.Agenda();
        a.adicionar("Ana", "111");
        a.adicionar("ana", "222");
        assertEquals(1, a.tamanho());
        assertEquals("222", a.buscar("ANA").orElseThrow());
    }

    @Test void listagemOrdenada() {
        var a = new Solution.Agenda();
        a.adicionar("bruno", "2"); a.adicionar("Ana", "1");
        assertEquals(java.util.List.of("Ana", "bruno"), a.listarOrdenado());
    }

    @Test void removeEAusente() {
        var a = new Solution.Agenda();
        a.adicionar("Ana", "1");
        assertTrue(a.remover("ana"));
        assertFalse(a.remover("ana"));
        assertTrue(a.buscar("Ana").isEmpty());
    }
}
